  const outlineCache=new Map(), inkMaterials=new Map()
  function ink(color) {
    if(!inkMaterials.has(color)) inkMaterials.set(color,new T.MeshBasicMaterial({color,toneMapped:false}))
    return inkMaterials.get(color)
  }
  function containsPoint(points, point) {
    let inside=false
    for(let i=0,j=points.length-1;i<points.length;j=i++) {
      const a=points[i],b=points[j]
      if((a.y>point.y)!==(b.y>point.y) &&
         point.x<(b.x-a.x)*(point.y-a.y)/(b.y-a.y)+a.x) inside=!inside
    }
    return inside
  }
  function glyphShapes(path) {
    // The embedded font uses positive winding for ink and negative winding for counters.
    const contours=path.subPaths.map(curve=>{
      const points=curve.getPoints(10)
      return {curve,points,area:T.ShapeUtils.area(points)}
    })
    const outlines=contours.filter(contour=>contour.area>0).sort((a,b)=>a.area-b.area)
    const shapes=outlines.map(({curve})=>{
      const shape=new T.Shape()
      shape.curves=curve.curves
      return shape
    })
    for(const {curve,points,area} of contours) {
      if(area>=0) continue
      const owner=outlines.findIndex(outline=>outline.area>-area &&
        points.every(point=>containsPoint(outline.points,point)))
      if(owner>=0) shapes[owner].holes.push(curve)
    }
    return shapes
  }
  function vectorText(parent,name,text,x,y,z,size,{align='left',middle=false,width=Infinity,color='#273737'}={}) {
    if(!outlineCache.has(text)) {
      const shapes=[]
      let offset=0
      for(const char of text) {
        const path=new T.ShapePath()
        const [advance,commands]=glyphs[char]??glyphs[' ']
        for(const [op,a,b,c,d,e,f] of commands) {
          if(op===0) path.moveTo(offset+a,b)
          else if(op===1) path.lineTo(offset+a,b)
          else if(op===2) path.quadraticCurveTo(offset+a,b,offset+c,d)
          else if(op===3) path.bezierCurveTo(offset+a,b,offset+c,d,offset+e,f)
          else path.currentPath.closePath()
        }
        shapes.push(...glyphShapes(path))
        offset+=advance
      }
      const geometry=new T.ShapeGeometry(shapes,10)
      geometry.computeBoundingBox()
      outlineCache.set(text,{geometry,offset})
    }
    const {geometry,offset}=outlineCache.get(text)
    const scale=Math.min(size/1000,width/offset)
    const shift=align==='center'?offset*.5:align==='right'?offset:0
    const base=middle?(geometry.boundingBox.min.y+geometry.boundingBox.max.y)*.5:0
    const mesh=piece(parent,name,geometry,ink(color),x-shift*scale,y-base*scale,z)
    mesh.scale.set(scale,scale,1)
    mesh.userData.vectorText=text
    return mesh
  }
  function flatRect(parent,name,w,h,x,y,z,color) {
    return piece(parent,name,new T.PlaneGeometry(w,h),ink(color),x,y,z)
  }

